import subprocess, json

def call(tool, args):
    subprocess.run(f"ft2 call {tool} '{json.dumps(args)}'", shell=True, capture_output=True, text=True)

# Set clean loop order: 0 -> 1 -> 2 -> 3 -> 1 -> 0 (loops cleanly)
# Actually for a keygen loop, let's make order: 0,1,2,1,0 with loop_start=0
call("song_set", {"length":5, "loop_start":0})
for i in range(5):
    if i == 0: call("order_set", {"position":i, "pattern":0})
    elif i == 1: call("order_set", {"position":i, "pattern":1})
    elif i == 2: call("order_set", {"position":i, "pattern":2})
    elif i == 3: call("order_set", {"position":i, "pattern":1})
    elif i == 4: call("order_set", {"position":i, "pattern":0})

print("Fixed order to loop cleanly")
